import { updateAssignmentInfo, type AssignmentInfoBody, type AssignmentInfoResponse } from '~/client';

export const useUpdateAssignmentInfo = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (vars: {
      projectId: string;
      userId: string;
      body: AssignmentInfoBody;
      cacheKey: string;
      cacheParent: string;
    }): Promise<AssignmentInfoResponse> =>
      updateAssignmentInfo({
        composable: '$fetch',
        path: { project_id: vars.projectId, user_id: vars.userId },
        body: ref(vars.body),
      }),
    onSuccess: async (_, vars) => {
      showToastSuccess('Assignment info updated successfully');
      await queryCache.invalidateQueries({ key: [vars.cacheKey, vars.cacheParent] });
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    updateAssignmentInfo: mutateAsync,
    isUpdatingAssignmentInfo: computed(() => asyncStatus.value === 'loading'),
  };
});
