<template>
  <EntityNote
    :note="note"
    :is-note-draft="isNoteDraft"
    :change-note-draft="changeNoteDraft"
    :update-note="onUpdate"
    :remove-note="onRemove"
    :is-update-loading="isAssignmentNoteUpdateLoading"
    :is-remove-loading="isAssignmentNoteRemoveLoading"
  />
</template>

<script setup lang="ts">
import type { Note } from '~/client';
import { useAssignmentNoteRemove, useAssignmentNoteUpdate } from '~/mutations/assignments/index';

const props = defineProps<{
  userId: string;
  projectId: string;
  note: Note | null;
  cacheKey: string;
  cacheParent: string;
  isNoteDraft: boolean;
  changeNoteDraft: () => void;
}>();

const { assignmentNoteUpdate, isAssignmentNoteUpdateLoading } = useAssignmentNoteUpdate();
const { assignmentNoteRemove, isAssignmentNoteRemoveLoading } = useAssignmentNoteRemove();

async function onUpdate(content: string) {
  await assignmentNoteUpdate({
    userId: props.userId,
    projectId: props.projectId,
    content,
    cacheKey: props.cacheKey,
    cacheParent: props.cacheParent,
  });
}

async function onRemove() {
  await assignmentNoteRemove({
    userId: props.userId,
    projectId: props.projectId,
    cacheKey: props.cacheKey,
    cacheParent: props.cacheParent,
  });
}
</script>
