import {
  updateUserToProjectAssignmentStatus,
  type AssignmentStatusUpdateResponse,
  type AssignmentStatus,
} from '~/client';

export const useUpdateAssignmentStatus = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (vars: {
      userId: string;
      projectId: string;
      assignmentStatus: AssignmentStatus;
      page: number;
      cacheKey: string;
      cacheParent: string;
    }): Promise<AssignmentStatusUpdateResponse> =>
      updateUserToProjectAssignmentStatus({
        composable: '$fetch',
        path: { user_id: vars.userId, project_id: vars.projectId },
        body: { assignment_status: vars.assignmentStatus },
      }),
    onSuccess: async (_, vars) => {
      showToastSuccess('Assignment status updated successfully');
      await queryCache.invalidateQueries({ key: [vars.cacheKey, vars.cacheParent] });
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    updateAssignmentStatus: mutateAsync,
    isUpdatingAssignmentStatusLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
