<template>
  <Card>
    <CardHeader>
      <CardTitle>Actions</CardTitle>
    </CardHeader>
    <CardContent class="flex flex-col gap-3">
      <div v-if="isCanvasserLike" class="flex flex-col gap-1">
        <p class="text-sm text-accent-foreground">Assignment status</p>
        <div class="flex gap-2 items-center">
          <LabeledSelect
            :items="assignmentStatusItems"
            :model-value="getAssignmentStatusItem(assignment.assignment_status)"
            @update:model-value="onSelectStatus"
          />
        </div>
        <ConfirmationDialog
          v-if="pendingStatus"
          v-model:model-value="isStatusModalOpen"
          title="Assignment status update"
          :description="`Do you want to set ${pendingStatus.name} status?`"
          :is-confirm-loading="isUpdatingAssignmentStatusLoading"
          @confirm="confirmUpdateStatus"
        />
      </div>

      <ConfirmationDialog
        v-if="isAdmin || (isManager && isCanvasserLike)"
        title="Remove assignment?"
        :description="`Do you want to remove this user from the project?`"
        :is-confirm-loading="isUnassigningUser"
        @confirm="onUnassign"
      >
        <Button variant="destructive" class="w-full" :prepend-icon="Trash" :loading="isUnassigningUser"
          >Unassign</Button
        >
      </ConfirmationDialog>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { Trash } from 'lucide-vue-next';
import type { AssignmentStatus, GetAssignmentDetailsResponse } from '~/client';
import { assignmentStatusItems } from '~/constants/assignments/assignmentStatusConfig';
import { useUpdateAssignmentStatus } from '~/mutations/assignments';

const props = defineProps<{
  assignment: GetAssignmentDetailsResponse;
  refetch: () => void;
}>();

const { isAdmin, isManager } = useUserRole();

const isCanvasserLike = computed(
  () => props.assignment.user_role === 'canvasser' || props.assignment.user_role === 'subcontractor_canvasser'
);

const pendingStatus = ref<SelectItem | null | undefined>(null);
const isStatusModalOpen = ref(false);

const { updateAssignmentStatus, isUpdatingAssignmentStatusLoading } = useUpdateAssignmentStatus();

function onSelectStatus(value: null | undefined | SelectItem) {
  pendingStatus.value = value;
  if (value) isStatusModalOpen.value = true;
}

async function confirmUpdateStatus() {
  if (!pendingStatus.value) return;
  await updateAssignmentStatus({
    userId: props.assignment.user_id,
    projectId: props.assignment.project_id,
    assignmentStatus: pendingStatus.value.value as AssignmentStatus,
    page: 1,
    cacheKey: 'assignment.details',
    cacheParent: `${props.assignment.project_id}:${props.assignment.user_id}`,
  });
  isStatusModalOpen.value = false;
  pendingStatus.value = null;
  props.refetch();
}

const { unassignUser, isUnassigningUser } = useUnassignUserFromProject();
const { navigateBack } = useNavJourney();

async function onUnassign() {
  await unassignUser({
    user_id: props.assignment.user_id,
    project_id: props.assignment.project_id,
    page: 1,
    cacheKey: 'assignment.details',
    cacheParent: `${props.assignment.project_id}:${props.assignment.user_id}`,
  });

  await navigateBack({ name: 'projects-id-assignments', params: { id: props.assignment.project_id } });
}
</script>
