import { editProjectAssignmentNote, type UserProjectsNoteEditResponse } from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useAssignmentNoteUpdate = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (vars: {
      userId: string;
      projectId: string;
      content: string;
      cacheKey: string;
      cacheParent: string;
    }): Promise<UserProjectsNoteEditResponse> =>
      editProjectAssignmentNote({
        composable: '$fetch',
        body: { content: vars.content },
        path: { user_id: vars.userId, project_id: vars.projectId },
      }),
    onSuccess: async (_, { cacheParent, cacheKey }) => {
      showToastSuccess('Note updated successfully');
      await queryCache.invalidateQueries({ key: [cacheKey, cacheParent] });
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    assignmentNoteUpdate: mutateAsync,
    isAssignmentNoteUpdateLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
