import { removeProjectAssignmentNote, type RemoveProjectAssignmentNoteResponse } from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useAssignmentNoteRemove = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (vars: {
      userId: string;
      projectId: string;
      cacheKey: string;
      cacheParent: string;
    }): Promise<RemoveProjectAssignmentNoteResponse> =>
      removeProjectAssignmentNote({
        composable: '$fetch',
        path: { user_id: vars.userId, project_id: vars.projectId },
      }),
    onSuccess: async (_, { cacheKey, cacheParent }) => {
      showToastSuccess('Note removed successfully');
      await queryCache.invalidateQueries({ key: [cacheKey, cacheParent] });
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    assignmentNoteRemove: mutateAsync,
    isAssignmentNoteRemoveLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
