<template>
  <div class="grid grid-cols-3 gap-4 md:gap-5">
    <div class="flex flex-col gap-4 col-span-3 xl:col-span-2 order-2 xl:order-1 md:gap-5">
      <AppEmpty v-if="!assignment" subject="assignment details" />
      <template v-else>
        <AssignmentsDetailsSummaryCard :assignment="assignment" />

        <AssignmentsDetailsInfoCard :assignment="assignment" />

        <template v-if="isCanvasserLike">
          <Card v-if="!assignment.note && !isNoteDraft">
            <CardHeader>
              <CardTitle>Note</CardTitle>
            </CardHeader>
            <CardContent>
              <p class="text-sm text-muted-foreground">
                No note has been created for this assignment yet. You can add a note to keep track of important
                information.
              </p>
            </CardContent>
            <CardFooter>
              <Button variant="outline" :prepend-icon="NotebookPenIcon" @click="isNoteDraft = true"
                >Create a Note</Button
              >
            </CardFooter>
          </Card>
          <AssignmentsNote
            v-else
            :user-id="assignment.user_id"
            :project-id="assignment.project_id"
            :note="assignment.note"
            cache-key="assignment.details"
            :cache-parent="cacheParent"
            :is-note-draft="isNoteDraft"
            :change-note-draft="() => (isNoteDraft = false)"
          />
        </template>
      </template>
    </div>

    <div class="col-span-3 xl:col-span-1 order-1 xl:order-2 h-fit">
      <AssignmentsDetailsActions v-if="assignment" :assignment="assignment" :refetch="refetch" />
    </div>
  </div>
</template>

<script setup lang="ts">
import { NotebookPenIcon } from 'lucide-vue-next';
import type { GetAssignmentDetailsResponse } from '~/client';

definePageMeta({
  backGroup: 'assignment-details',
  backLabel: 'assignment',
});

const props = defineProps<{
  assignment: GetAssignmentDetailsResponse | null | undefined;
  refetch: () => void;
}>();

const isCanvasserLike = computed(
  () => props.assignment?.user_role === 'canvasser' || props.assignment?.user_role === 'subcontractor_canvasser'
);

const isNoteDraft = ref(false);

const cacheParent = computed(() =>
  props.assignment ? `${props.assignment.project_id}:${props.assignment.user_id}` : ''
);
</script>
