<template>
  <Card>
    <CardHeader class="flex flex-row items-center justify-between gap-2">
      <CardTitle>Configuration</CardTitle>
      <Dialog v-model:open="isOpen" @update:open="onDialogOpen">
        <DialogTrigger as-child>
          <Button v-if="isAdmin" variant="outline" size="sm" :prepend-icon="PencilIcon">Edit</Button>
        </DialogTrigger>
        <DialogContent class="rounded-lg max-w-xs sm:max-w-sm md:max-w-5xl px-0 gap-6">
          <DialogHeader class="px-6 gap-y-2 text-left">
            <DialogTitle class="text-xl">Edit assignment info</DialogTitle>
            <DialogDescription v-if="isRegularCanvasser" class="font-normal text-base text-accent-foreground">
              Changing the pay rate terminates any pending or active contract and issues a new one.
            </DialogDescription>
            <DialogDescription v-else />
          </DialogHeader>

          <form v-if="userShort" id="assignmentInfoEdit" class="px-6" @submit.prevent="onSubmit">
            <AssignmentInfoForm
              mode="edit"
              :user-id="assignment.user_id"
              :user-role="assignment.user_role"
              :user-full-name="username(userShort)"
              :project-id="assignment.project_id"
              :project-name="projectShort?.name ?? ''"
              :project-type="assignment.project_type"
              :payment="assignment.project_payment"
              :existing-increased-pay-rate="assignment.increased_price_per_hour"
            />
          </form>

          <DialogFooter class="px-6">
            <div class="flex flex-wrap justify-end gap-2">
              <DialogClose as-child>
                <Button variant="outline" class="h-10 px-4">Cancel</Button>
              </DialogClose>
              <Button class="h-10 px-4" type="submit" form="assignmentInfoEdit" :loading="isUpdatingAssignmentInfo">
                Save
              </Button>
            </div>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </CardHeader>
    <CardContent class="grid grid-cols-1 sm:grid-cols-2 gap-4">
      <LabeledValueIcon v-if="isRegularCanvasser" label="Pay rate" :value="payRateLabel" :icon="BanknoteIcon" />
      <LabeledValueIcon
        v-if="isRegularCanvasser && assignment.project_type === 'canvassing' && isIncreasedPayRateEnabled"
        label="Increased pay rate"
        :value="increasedPayRateLabel"
        :icon="TrendingUpIcon"
      />
      <LabeledValueIcon
        v-if="isRegularCanvasser"
        label="Assignment type"
        :value="assignmentTypeLabel"
        :icon="BriefcaseBusinessIcon"
      />
      <LabeledValueIcon
        v-if="isCanvasserLike && assignment.project_type === 'canvassing'"
        label="Canvassing app username"
        :value="assignment.canvassing_application_username ?? '-'"
        :icon="AtSignIcon"
      />
      <LabeledValueIcon label="Position" :value="assignment.position ?? '-'" :icon="UserCogIcon" />
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import {
  AtSignIcon,
  BanknoteIcon,
  BriefcaseBusinessIcon,
  PencilIcon,
  TrendingUpIcon,
  UserCogIcon,
} from 'lucide-vue-next';
import { toTypedSchema } from '@vee-validate/zod';
import { useForm } from 'vee-validate';
import type { GetAssignmentDetailsResponse } from '~/client';
import { getUserShortInfo, getProjectShortInfo } from '~/client';
import { getAssignmentType } from '~/constants/assignments/assignmentTypes';
import { buildAssignmentInfoSchema } from '~/constants/validationSchemas/assignmentInfo';
import { useUpdateAssignmentInfo } from '~/mutations/assignments';

const props = defineProps<{
  assignment: GetAssignmentDetailsResponse;
}>();

const isRegularCanvasser = computed(() => props.assignment.user_role === 'canvasser');
const isCanvasserLike = computed(
  () => props.assignment.user_role === 'canvasser' || props.assignment.user_role === 'subcontractor_canvasser'
);

const { isAdmin } = useUserRole();

const { data: userShort } = useQuery({
  key: () => ['user.short-info', props.assignment.user_id],
  query: () => getUserShortInfo({ composable: '$fetch', path: { user_id: props.assignment.user_id } }),
  enabled: () => !!props.assignment.user_id,
});

const { data: projectShort } = useQuery({
  key: () => ['project.short-info', props.assignment.project_id],
  query: () => getProjectShortInfo({ composable: '$fetch', path: { project_id: props.assignment.project_id } }),
  enabled: () => !!props.assignment.project_id,
});

const payRateLabel = computed(() => {
  if (typeof props.assignment.price_per_hour === 'number') return `$${props.assignment.price_per_hour.toFixed(2)} / hr`;
  if (typeof props.assignment.price_per_signature === 'number')
    return `$${props.assignment.price_per_signature.toFixed(2)} / signature`;
  return '-';
});

const increasedPayRateLabel = computed(() =>
  typeof props.assignment.increased_price_per_hour === 'number'
    ? `$${props.assignment.increased_price_per_hour.toFixed(2)} / hr`
    : '-'
);

const isIncreasedPayRateEnabled = computed(() =>
  isIncreasedPayRateApplicable(props.assignment.project_payment, props.assignment.increased_price_per_hour)
);

const assignmentTypeLabel = computed(() =>
  props.assignment.assignment_type ? getAssignmentType(props.assignment.assignment_type).name : '-'
);

const isOpen = ref(false);

const schema = computed(() =>
  toTypedSchema(
    buildAssignmentInfoSchema({
      projectType: props.assignment.project_type,
      paymentEnabled: props.assignment.project_payment.payments_enabled,
      increasedPayRateEnabled: isIncreasedPayRateEnabled.value,
      payRateApplicable: isRegularCanvasser.value,
      canvassingAppUsernameApplicable: isCanvasserLike.value,
      mode: 'edit',
    })
  )
);

const { handleSubmit, setValues, resetForm } = useForm({
  validationSchema: schema,
});

const { updateAssignmentInfo, isUpdatingAssignmentInfo } = useUpdateAssignmentInfo();

function onDialogOpen(open: boolean) {
  if (!open) {
    resetForm();
    return;
  }
  if (!isRegularCanvasser.value) {
    setValues(
      {
        canvasser_in_app: props.assignment.canvassing_application_username ?? null,
        position: props.assignment.position ?? null,
      },
      false
    );
    return;
  }
  setValues(
    {
      assignment_type: props.assignment.assignment_type ?? undefined,
      rate:
        props.assignment.project_type === 'canvassing'
          ? props.assignment.price_per_hour != null
            ? String(props.assignment.price_per_hour)
            : null
          : props.assignment.price_per_signature != null
            ? String(props.assignment.price_per_signature)
            : null,
      increased_price_per_hour:
        props.assignment.project_type === 'canvassing' && props.assignment.increased_price_per_hour != null
          ? String(props.assignment.increased_price_per_hour)
          : null,
      canvasser_in_app: props.assignment.canvassing_application_username ?? null,
      position: props.assignment.position ?? null,
    },
    false
  );
}

const onSubmit = handleSubmit(async (values) => {
  const isCanvassing = props.assignment.project_type === 'canvassing';
  await updateAssignmentInfo({
    projectId: props.assignment.project_id,
    userId: props.assignment.user_id,
    body: {
      price_per_signature:
        isRegularCanvasser.value && props.assignment.project_type === 'signature' ? (values.rate ?? null) : null,
      price_per_hour: isRegularCanvasser.value && isCanvassing ? (values.rate ?? null) : null,
      assignment_type: isRegularCanvasser.value ? (values.assignment_type ?? null) : null,
      canvassing_application_username: isCanvassing ? (values.canvasser_in_app ?? null) : null,
      increased_price_per_hour:
        isRegularCanvasser.value && isCanvassing ? (values.increased_price_per_hour ?? null) : null,
      // Sent even when null — blanking it is how a member is taken off the customer-facing roster.
      position: values.position ?? null,
    },
    cacheKey: 'assignment.details',
    cacheParent: `${props.assignment.project_id}:${props.assignment.user_id}`,
  });
  isOpen.value = false;
});
</script>
