import { unassignUserFromProject } from '~/client';

export const useUnassignUserFromProject = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync: unassignUser, asyncStatus } = useMutation({
    mutation: (data: { user_id: string; project_id: string; page: number; cacheKey: string; cacheParent: string }) =>
      unassignUserFromProject({
        composable: '$fetch',
        path: {
          user_id: data.user_id,
          project_id: data.project_id,
        },
      }),
    onSuccess: (_, requestData) => {
      queryCache.invalidateQueries({
        key: [requestData.cacheKey, requestData.cacheParent],
      });
      if (useRoute().name === 'users-id')
        queryCache.invalidateQueries({ key: ['selector-unassigned-projects', requestData.user_id] });
      showToastSuccess('User unassigned successfully');
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    unassignUser,
    isUnassigningUser: computed(() => asyncStatus.value === 'loading'),
  };
});
